from collections import Counter
from pathlib import Path
from random import Random
from string import ascii_lowercase
import hashlib
import json
import math

from vs import refcorpus

WORKS = {
    "latin": ("la_augustine", "la_erasmus"),
    "italian": ("it_dante", "it_villani"),
    "spanish": ("es_lucanor", "es_buenamor"),
    "english": ("en_chaucer", "en_paston"),
}
MAX_ORDER = 8
ALPHA = 2
PAD = "BD"
out = Path(__file__).parent

def make_options(train):
    def deterministic(c):
        return "B" if ascii_lowercase.index(c) % 2 else "D"

    counts = Counter(deterministic(c) for line in train for c in line if c != " ")
    prob = counts["B"] / (counts["B"] + counts["D"])
    rng = Random(408)
    letters = list(ascii_lowercase)
    rng.shuffle(letters)
    forward = str.maketrans(ascii_lowercase, "".join(letters))
    backward = str.maketrans("".join(letters), ascii_lowercase)
    strip = str.maketrans("", "", PAD)

    def transform(line, mode, rng):
        if mode == "identity":
            return line
        if mode == "substitution":
            return line.translate(forward)
        if mode == "suffix_B":
            return " ".join(word + "B" for word in line.split())
        pieces = []
        for c in line:
            pieces.append(c)
            if c == " ":
                continue
            if mode == "addB":
                pieces.append("B")
            elif mode == "matched_deterministic":
                pieces.append(deterministic(c))
            elif mode == "matched_random":
                pieces.append("B" if rng.random() < prob else "D")
        return "".join(pieces)

    def inverse(line, mode):
        if mode == "substitution":
            return line.translate(backward)
        return line.translate(strip)

    return transform, inverse, prob

def fit_score(train, test, alphabet):
    counts = [{} for _ in range(MAX_ORDER + 1)]
    counts[0][""] = Counter()
    for line in train:
        for i, c in enumerate(line):
            for k in range(min(i, MAX_ORDER) + 1):
                key = line[i-k:i]
                group = counts[k].get(key)
                if group is None:
                    group = Counter()
                    counts[k][key] = group
