"""Independent entropy-form and cumulative-sampling audit of frozen results."""
import bisect
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from itertools import accumulate
from pathlib import Path

from vs import refcorpus
import right_context as experiment

ROOT = Path(__file__).resolve().parent


def entropy(probabilities):
    return -math.fsum(p * math.log2(p) for p in probabilities if p)


def entropy_js(counts_p, counts_q):
    alphabet = sorted(counts_p.keys() | counts_q.keys())
    p = [counts_p[s] / sum(counts_p.values()) for s in alphabet]
    q = [counts_q[s] / sum(counts_q.values()) for s in alphabet]
    return entropy([(x+y)/2 for x, y in zip(p, q)]) - (entropy(p)+entropy(q))/2


def contexts(text, symbol, direction):
    # Find symbol positions rather than tabulating adjacent pairs with zip.
    return Counter(text[i+direction] for i, c in enumerate(text)
                   if c == symbol and 0 <= i+direction < len(text))


def score(text, candidate, a, b):
    left = entropy_js(contexts(text, candidate, -1), contexts(text, a, -1))
    right = entropy_js(contexts(text, candidate, 1), contexts(text, b, 1))
    return {'left_js': left, 'bilateral_js': (left+right)/2}


def verify_pair_rows(result):
    checked, maximum = 0, 0
    texts = {}
    for row in result['paired_rows']:
        if not row.get('pairs'):
            continue
        key = row['language'], row['partition']
        if key not in texts:
            texts[key] = experiment.source(*key)
        text = texts[key]
        pool = experiment.matching_pool(text, row['target'], row['decoy'], row['mode'], row['seed'])
        pairs = pool[:len(pool)//2] if row['fraction'] == .5 else pool
        encoded = experiment.plant(text, pairs)
        for candidate in ('X', 'Z'):
            actual = score(encoded, candidate, *row['target'])
            for method, value in actual.items():
                error = abs(value-row['scores'][candidate][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (row, candidate, method, error)
                cutoff = result['thresholds'][method]
                assert experiment.accepted(value, cutoff) == experiment.accepted(row['scores'][candidate][method], cutoff)
                checked += 1
    return checked, maximum


def tables_for(text):
    outgoing = defaultdict(Counter)
    for i in range(len(text)-1):
        outgoing[text[i]][text[i+1]] += 1
    def table(counts):
        symbols = sorted(counts)
        return symbols, list(accumulate(counts[s] for s in symbols))
    starts = table(Counter(w[0] for w in text.split()))
    normal = {c: table(counts) for c, counts in outgoing.items()}
    final = {c: table({s: n for s, n in counts.items() if s != ' '})
             for c, counts in outgoing.items()}
    return starts, normal, final


def direct_text(seed, tables):
    starts, normal, final = tables
    rng = random.Random(seed)
    def draw(table):
        symbols, cumulative = table
        return symbols[bisect.bisect_right(cumulative, rng.randrange(cumulative[-1]))]
    chars = [draw(starts)]
    for i in range(1, 40000):
        table = (final if i == 39999 else normal).get(chars[-1])
        chars.append(draw(table if table and table[0] else starts))
    return ''.join(chars)


def verify_negatives(result):
    checked, maximum = 0, 0
    streams, tables = {}, {}
    for row in result['negative_controls']:
        language, origin, sample = row['language'], row['origin'], row['sample']
        key = language, origin, sample
        if key not in streams:
            if origin == 'natural':
                streams[key] = experiment.source(language, 'evaluation')
            else:
                if language not in tables:
                    tables[language] = tables_for(experiment.source(language, 'training').strip())
                streams[key] = direct_text(sample, tables[language])
        text = streams[key]
        assert hashlib.sha256(text.encode()).hexdigest() == row['sha256']
        for candidate in row['candidates']:
            actual = score(text, candidate['candidate'], *row['target'])
            for method, value in actual.items():
                error = abs(value-candidate['scores'][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (key, row['target'], candidate, error)
                assert experiment.accepted(value, result['thresholds'][method]) == candidate['accepted'][method]
                checked += 1
    return checked, maximum, len(streams)


def main():
    calibration = json.loads((ROOT/'calibration.json').read_bytes())
    evaluation = json.loads((ROOT/'evaluation.json').read_bytes())
    p1, e1 = verify_pair_rows(calibration)
    p2, e2 = verify_pair_rows(evaluation)
    n, e3, samples = verify_negatives(evaluation)
    output = {'paired_js_values_verified': p1+p2, 'negative_js_values_verified': n,
              'distinct_negative_streams_verified': samples,
              'maximum_absolute_js_error': max(e1, e2, e3),
              'all_acceptance_decisions_match': True,
              'all_regenerated_negative_stream_hashes_match': True}
    (ROOT/'verification.json').write_text(json.dumps(output, indent=2))
    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()

scripts.original_triplet.py:
"""Public calibration of Matlach et al.'s eight-rule triplet score."""
import json
import math
import random
from bisect import bisect_right
from collections import Counter, defaultdict
from itertools import product

from vs import corpus, refcorpus

PROPORTION = 500 / 229431
WEIGHTS = (1, 100, 1, 1, 100, 1, 1, 10)
THRESHOLD = 0.05
LIMIT = 40000
CONTRASTS = {
    'english': [('th', 'to'), ('ea', 'er')],
    'latin': [('en', 'es'), ('pa', 'pe')],
    'italian': [('ch', 'co'), ('de', 'di')],
}
RATES = ((1, 4), (1, 2), (1, 1))
DRAFT_TRIPLETS = [('m','i','d'),('q','i','e'),('f','i','d'),('n','i',' '),('g','c','d')]


def glyph_counts(text):
    return Counter(text), Counter(zip(text, text[1:]))


def correlation(x, y):
    n = len(x)
    if n < 2:
        return 0.0
    mx, my = sum(x) / n, sum(y) / n
    xv = [a - mx for a in x]
    yv = [b - my for b in y]
    den = math.sqrt(sum(a*a for a in xv) * sum(b*b for b in yv))
    return min(1.0, abs(sum(a*b for a,b in zip(xv,yv)) / den)) if den else 0.0


class Score:
    def __init__(self, text, *, single_context_loss=0.0):
        count, raw = glyph_counts(text)
        rows, cols = Counter(), Counter()
        for (a, b), n in raw.items():
            rows[a] += n
            cols[b] += n
        kept = {pair: n for pair,n in raw.items()
                if 500*n >= rows[pair[0]] and 500*n >= cols[pair[1]]}
        self.p = {s: n / len(text) for s,n in count.items()}
        self.m = {edge: n / (len(text)-1) for edge,n in kept.items()}
        self.max_p = max(self.p.values())
        self.max_m = max(self.m.values())
        self.max_diag = max((value for (a,b),value in self.m.items() if a == b), default=1.0)
        self.alphabet = sorted(s for s,p in self.p.items() if s != ' ' and p > PROPORTION)
        self.context = {}
        self.context_sizes = {}
        for c,a in product(count, repeat=2):
            less, more = (a,c) if self.p[a] < self.p[c] else (c,a)
            order = [s for s in sorted(count) if (s,less) in self.m]
            rare = [self.m[s,less] for s in order]
            common = [self.m.get((s,more),0.0) for s in order]
            match = sum(r for r,v in zip(rare,common) if v)
            miss = sum(r for r,v in zip(rare,common) if not v)
            size = len(order)
            distribution = 1.0-correlation(rare,common) if size >= 2 else single_context_loss if size else 0.0
            self.context[c,a] = (match, miss, distribution)
            self.context_sizes[c,a] = size

    def losses(self, c,a,b, version):
        pc, pa, pb = self.p[c], self.p[a], self.p[b]
        matched, unmatched, distribution = self.context[c,a]
        return (
            max(0.0, pc-max(pa,pb))/self.max_p,
            self.m.get((a,b),0.0)/self.max_m,
            matched if version == 'literal' else unmatched,
            distribution,
            self.m.get((c,c),0.0)/self.max_diag,
            (1-min(pa,pb))/self.max_p if version == 'literal' else 1-min(pa,pb)/self.max_p,
            pc/((pa+pc)*(pb+pc)),
            float(a==b),
        )

    def total(self, triplet, version):
        return sum(w*x for w,x in zip(WEIGHTS,self.losses(*triplet,version)))

    def ranker(self, version):
        scores = sorted(self.total((c,a,b),version)
                        for c,a,b in product(self.alphabet, repeat=3) if c not in (a,b))

        def rank(triplet):
            if not all(s in self.p for s in triplet):
                return None
            t = self.total(triplet,version)
            return {
                'rank': bisect_right(scores,t)/len(scores),
                'loss': t,
                'competing': all(s in self.alphabet for s in triplet),
                'loss_left_context_rules': list(self.losses(*triplet,version)[2:4]),
                'rarer_left_contexts': self.context_sizes[triplet[0],triplet[1]],
            }

        return rank


def start_positions(text, first, second, by_left):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            couple = word[i:i+2]
            if couple in (first,second):
                # Share a word-initial/medial and a word-final/medial position class.
                key = (i == 0, i+2 == len(word))
                if by_left:
                    key += (word[i-1] if i else ' ',)
                groups[key][couple == second].append(offset+i)
        offset += len(word)+1
    return groups


def paired_positions(text, target, decoy, by_left, seed):
    groups = start_positions(text, target, decoy, by_left)
    rng = random.Random(seed)
    occupied = set()
    paired = []
    for key,(left,right) in sorted(groups.items()):
        rng.shuffle(left)
        rng.shuffle(right)
        for i,j in zip(left,right):
            # Each edit consumes i and i+1 and must have an unedited neighbor.
            if abs(i-j) < 3 or i in occupied or j in occupied:
                continue
            occupied.update(range(i-2,i+3))
            occupied.update(range(j-2,j+3))
            paired.append((i,j))
    rng.shuffle(paired)
    return paired


def encode(text, pairs):
    edits = sorted([(i,'X') for i,j in pairs] + [(j,'Z') for i,j in pairs])
    fragments = []
    after = 0
    for start, symbol in edits:
        fragments.extend((text[after:start],symbol))
        after = start+2
    fragments.append(text[after:])
    return ''.join(fragments)


def euler_surrogate(text, seed):
    outgoing = defaultdict(list)
    for a,b in zip(text,text[1:]):
        outgoing[a].append(b)
    rng = random.Random(seed)
    for a in sorted(outgoing):
        rng.shuffle(outgoing[a])
    stack = [text[0]]
    path = []
    while stack:
        v = stack[-1]
        if outgoing[v]:
            stack.append(outgoing[v].pop())
        else:
            path.append(stack.pop())
    result = ''.join(reversed(path))
    assert len(result) == len(text)
    assert glyph_counts(result) == glyph_counts(text)
    return result


def fixed_match_tests():
    rows = []
    euler = []
    for lang, contrasts in CONTRASTS.items():
        for partition, loader in (('train',refcorpus.train_text),('control',refcorpus.control_text)):
            text = (' ' + ' '.join(loader(lang))[:LIMIT].rsplit(' ',1)[0] + ' ')
            for index,(target,decoy) in enumerate(contrasts):
                for match in ('word_slots','word_slots_and_left'):
                    paired = paired_positions(text,target,decoy,match == 'word_slots_and_left',9141+index)
                    for num,den in RATES:
                        used = paired[:len(paired)*num//den]
                        if not used:
                            continue
                        trial_text = encode(text,used)
                        count, bigrams = glyph_counts(trial_text)
                        assert count['X'] == count['Z'] == len(used)
                        assert bigrams['X','X'] == bigrams['Z','Z'] == 0
                        incoming_delta = sum(abs(bigrams[s,'X']-bigrams[s,'Z']) for s in count)
                        outgoing_delta = sum(abs(bigrams['X',s]-bigrams['Z',s]) for s in count)
                        if match == 'word_slots_and_left':
                            assert incoming_delta == 0
                        calculator = Score(trial_text)
                        row = {
                            'language':lang, 'partition':partition, 'target':target, 'decoy':decoy,
                            'matching':match, 'fraction_of_matched_pool':num/den, 'n_pairs':len(used),
                            'pool':len(paired), 'source_target_occurrences':text.count(target),
                            'source_decoy_occurrences':text.count(decoy), 'characters':len(trial_text),
                            'incoming_count_L1':incoming_delta, 'outgoing_count_L1':outgoing_delta,
                            'scores':{},
                        }
                        for version in ('literal','prose'):
                            ranks = calculator.ranker(version)
                            paired_scores = {symbol:ranks((symbol,*target)) for symbol in ('X','Z')}
                            if match == 'word_slots_and_left':
                                assert paired_scores['X'] == paired_scores['Z']
                            row['scores'][version] = paired_scores
                        rows.append(row)
                        if partition == 'control' and num == den and index == 0 and match == 'word_slots':
                            surrogate = euler_surrogate(trial_text,7073)
                            comparator = Score(surrogate)
                            for version in ('literal','prose'):
                                original = calculator.ranker(version)
                                new = comparator.ranker(version)
                                assert original(('X',*target)) == new(('X',*target))
                                losses = [calculator.total(t,version) for t in product(calculator.alphabet,repeat=3)
                                          if t[0] not in t[1:]]
                                other = [comparator.total(t,version) for t in product(comparator.alphabet,repeat=3)
                                         if t[0] not in t[1:]]
                                assert losses == other
                            euler.append({'language':lang,'target':target, 'identical_triplet_losses':len(losses),
                                          'fraction_changed_slots':sum(x!=y for x,y in zip(trial_text,surrogate))/len(trial_text),
                                          'length':len(trial_text)})
    return rows,euler


def manuscript():
    out = {}
    for name in ('zl','it'):
        partitions = {}
        for part,pages in zip(('train','evaluation'),corpus.split_pages('practice',name)):
            text = ' '.join(word for page in pages for line in page.lines if line.unit == 'P'
                            for word in line.words if word.isascii() and word.isalpha())
            options = {}
            for single_loss in (0.0,1.0):
                calc = Score(text,single_context_loss=single_loss)
                versions = {}
                for version in ('literal','prose'):
                    lookup = calc.ranker(version)
                    versions[version] = {'|'.join(t):lookup(t) for t in DRAFT_TRIPLETS}
                options[str(single_loss)] = versions
            partitions[part] = {'length':len(text), 'singleton_context_loss':options}
        out[name] = partitions
    return out


def clean_lines(pages):
    return [' '.join(word for word in line.words if word.isascii() and word.isalpha())
            for page in pages for line in page.lines if line.unit == 'P']


def stationary_chain():
    results = {}
    for edition in ('zl','it'):
        train,test = corpus.split_pages('practice',edition)
        source = [line for line in clean_lines(train) if line]
        lengths = [len(line) for line in clean_lines(test) if line]
        starts = [line[0] for line in source]
        outgoing = defaultdict(list)
        for line in source:
            for a,b in zip(line,line[1:]):
                outgoing[a].append(b)
        end_neighbors = {a:[b for b in next_symbols if b != ' ']
                         for a,next_symbols in outgoing.items()}
        cases = []
        for seed in range(7810,7816):
            rng = random.Random(seed)
            lines = []
            for length in lengths:
                glyphs = [rng.choice(starts)]
                for i in range(1,length):
                    table = end_neighbors if i == length-1 else outgoing
                    glyphs.append(rng.choice(table.get(glyphs[-1]) or starts))
                lines.append(''.join(glyphs))
            assert [len(line) for line in lines] == lengths
            text = ' '.join(lines)
            assert '  ' not in text
            calc = Score(text)
            measurements = {}
            for version in ('literal','prose'):
                rank = calc.ranker(version)
                measurements[version] = {'|'.join(t):rank(t) for t in DRAFT_TRIPLETS}
            cases.append({'seed':seed,'length':len(text),'measurements':measurements})
        results[edition] = cases
    return results


def summarize(rows):
    summary = {}
    for name in ('word_slots','word_slots_and_left'):
        group = [r for r in rows if r['matching'] == name]
        by_version = {}
        for version in ('literal','prose'):
            counts = {}
            for fraction in (0.25,0.5,1.0):
                candidates = [row['scores'][version] for row in group if row['fraction_of_matched_pool'] == fraction]
                eligible = [pair for pair in candidates if pair['X']['competing'] and pair['Z']['competing']]
                tally = Counter()
                for pair in eligible:
                    x,z = pair['X'],pair['Z']
                    tally['genuine_lower' if x['loss'] < z['loss']-1e-12 else
                          'decoy_lower' if z['loss'] < x['loss']-1e-12 else 'tied'] += 1
                    tally['both_below_5pct'] += x['rank'] <= THRESHOLD and z['rank'] <= THRESHOLD
                    tally['genuine_below_5pct'] += x['rank'] <= THRESHOLD
                counts[fraction] = {'eligible':len(eligible),'all':len(candidates),**tally}
            by_version[version] = counts
        summary[name] = by_version
    return summary


if __name__ == '__main__':
    pairs,exact_bigrams = fixed_match_tests()
    print(json.dumps({'summary':summarize(pairs),'same_bigram_surrogates':exact_bigrams,
                      'manuscript':manuscript(),'stationary_chain':stationary_chain(),'paired_runs':pairs}, indent=2))

scripts.right_context.py:
"""Frozen public calibration/evaluation of a bilateral-context ligature loss.

Run from the repository root, on PYTHONPATH. No manuscript input is read.
"""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus
from original_triplet import Score

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT / 'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
PLAN_HASH = hashlib.sha256(PLAN_BYTES).hexdigest()
METHODS = ('left_js', 'bilateral_js', 'eight_rule_prose')
TOL = 1e-12


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    if not np or not nq:
        raise ValueError('empty context distribution')
    total = 0.0
    for symbol in sorted(p.keys() | q.keys()):
        x, y = p[symbol] / np, q[symbol] / nq
        midpoint = (x + y) / 2
        if x:
            total += x * math.log2(x / midpoint) / 2
        if y:
            total += y * math.log2(y / midpoint) / 2
    return total


class Context:
    def __init__(self, text):
        self.count = Counter(text)
        self.incoming, self.outgoing = defaultdict(Counter), defaultdict(Counter)
        for a, b in zip(text, text[1:]):
            self.incoming[b][a] += 1
            self.outgoing[a][b] += 1
        self.baseline = Score(text)

    def eligible(self, c, a, b):
        return all(self.count[s] >= 40 and self.incoming[s] and self.outgoing[s] for s in (c, a, b))

    def scores(self, c, a, b):
        left = js(self.incoming[c], self.incoming[a])
        right = js(self.outgoing[c], self.outgoing[b])
        return {'left_js': left, 'bilateral_js': (left + right) / 2,
                'eight_rule_prose': self.baseline.total((c, a, b), 'prose')}


def source(language, partition):
    loader = {'calibration': refcorpus.calib_text, 'evaluation': refcorpus.control_text,
              'training': refcorpus.train_text}[partition]
    text = ' '.join(loader(language))
    if partition == 'evaluation':
        text = text[40000:].split(' ', 1)[1]
    return ' ' + text[:40000].rsplit(' ', 1)[0] + ' '


def matching_pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = {i: 'X' for i, _ in pairs} | {j: 'Z' for _, j in pairs}
    result, pos = [], 0
    while pos < len(text):
        if pos in edits:
            result.append(edits[pos])
            pos += 2
        else:
            result.append(text[pos])
            pos += 1
    return ''.join(result)


def paired_rows(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'partition': partition, 'characters': len(text),
                        'sha256': hashlib.sha256(text.encode()).hexdigest()})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for seed in PLAN['seeds']:
                    pool = matching_pool(text, target, decoy, mode, seed)
                    for fraction in PLAN['fractions']:
                        pairs = pool[:len(pool)//2] if fraction == .5 else pool
                        if not pairs:
                            rows.append({'language': language, 'partition': partition, 'target': target,
                                         'decoy': decoy, 'mode': mode, 'seed': seed, 'fraction': fraction,
                                         'eligible': False, 'pairs': 0})
                            continue
                        encoded = plant(text, pairs)
                        calculator = Context(encoded)
                        assert calculator.count['X'] == calculator.count['Z'] == len(pairs)
                        for i, j in pairs:
                            assert text[i:i+2] == target and text[j:j+2] == decoy
                            assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
                            if mode in ('left', 'both'):
                                assert text[i-1] == text[j-1]
                            if mode == 'both':
                                assert text[i+2] == text[j+2]
                        if mode in ('left', 'both'):
                            assert calculator.incoming['X'] == calculator.incoming['Z']
                        if mode == 'both':
                            assert calculator.outgoing['X'] == calculator.outgoing['Z']
                        sx, sz = calculator.scores('X', *target), calculator.scores('Z', *target)
                        if mode in ('left', 'both'):
                            assert abs(sx['left_js']-sz['left_js']) <= TOL
                        if mode == 'both':
                            assert all(abs(sx[k]-sz[k]) <= TOL for k in METHODS)
                        rows.append({'language': language, 'partition': partition, 'target': target,
                                     'decoy': decoy, 'mode': mode, 'seed': seed, 'fraction': fraction,
                                     'pairs': len(pairs), 'pool': len(pool),
                                     'eligible': bool(calculator.eligible('X', *target) and calculator.eligible('Z', *target)),
                                     'scores': {'X': sx, 'Z': sz}})
    return rows, sources


def primary(rows):
    return [r for r in rows if r['eligible'] and r['mode'] == 'left' and r['fraction'] == 1]


def accepted(score, cutoff):
    return cutoff is not None and score < cutoff-TOL


def summarize(rows, thresholds):
    summary = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            eligible = [r for r in selected if r['eligible']]
            row = {'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                   'eligible': len(eligible), 'methods': {}}
            for method in METHODS:
                tally = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in eligible:
                    x, z = r['scores']['X'][method], r['scores']['Z'][method]
                    tally['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    tally['accepted_X'] += accepted(x, thresholds[method])
                    tally['accepted_Z'] += accepted(z, thresholds[method])
                row['methods'][method] = dict(tally)
            summary.append(row)
    return summary


def sample_letters(text, language, origin, sample, thresholds):
    calc = Context(text)
    rows = []
    for target, _ in PLAN['contrasts'][language]:
        considered = []
        for c in sorted(calc.count):
            if not c.islower() or c in target or not calc.eligible(c, *target):
                continue
            scores = calc.scores(c, *target)
            considered.append({'candidate': c, 'scores': scores,
                               'accepted': {m: accepted(scores[m], thresholds[m]) for m in METHODS}})
        rows.append({'language': language, 'origin': origin, 'sample': sample,
                     'target': target, 'characters': len(text),
                     'sha256': hashlib.sha256(text.encode()).hexdigest(), 'candidates': considered})
    return rows


def negative_controls(thresholds):
    rows = []
    for language in PLAN['contrasts']:
        rows += sample_letters(source(language, 'evaluation'), language, 'natural', None, thresholds)
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        start_counts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for symbol, n in sorted(counts.items()):
                if point < n:
                    return symbol
                point -= n
            raise AssertionError('draw failed')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            text = [draw(rng, start_counts)]
            while len(text) < 40000:
                options = outgoing[text[-1]]
                if len(text) == 39999:
                    options = Counter({s: n for s, n in options.items() if s != ' '})
                text.append(draw(rng, options or start_counts))
            text = ''.join(text)
            assert '  ' not in text and text[-1] != ' '
            rows += sample_letters(text, language, 'direct_chain', seed, thresholds)
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    args = parser.parse_args()
    if args.phase == 'calibrate':
        rows, sources = paired_rows('calibration')
        eligible = primary(rows)
        thresholds = {}
        for method in METHODS:
            negatives = sorted(r['scores']['Z'][method] for r in eligible)
            thresholds[method] = negatives[math.floor(.05*len(negatives))] if negatives else None
        output = {'plan_sha256': PLAN_HASH, 'script_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                  'thresholds': thresholds, 'threshold_negative_count': len(eligible),
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows}
        filename = 'calibration.json'
    else:
        frozen_bytes = (ROOT / 'calibration.json').read_bytes()
        frozen = json.loads(frozen_bytes)
        assert frozen['plan_sha256'] == PLAN_HASH
        assert frozen['script_sha256'] == hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
        rows, sources = paired_rows('evaluation')
        output = {'plan_sha256': PLAN_HASH, 'calibration_sha256': hashlib.sha256(frozen_bytes).hexdigest(),
                  'sources': sources, 'thresholds': frozen['thresholds'],
                  'summary': summarize(rows, frozen['thresholds']), 'paired_rows': rows,
                  'negative_controls': negative_controls(frozen['thresholds'])}
        filename = 'evaluation.json'
    (ROOT / filename).write_text(json.dumps(output, indent=2), encoding='utf-8')
    print(json.dumps({'phase': args.phase, 'primary_eligible': len(primary(rows)),
                      'thresholds': output['thresholds'], 'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts.verify_right_context.py:
"""Independent entropy-form and cumulative-sampling audit of frozen results."""
import bisect
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from itertools import accumulate
from pathlib import Path

from vs import refcorpus
import right_context as experiment

ROOT = Path(__file__).resolve().parent


def entropy(probabilities):
    return -math.fsum(p * math.log2(p) for p in probabilities if p)


def entropy_js(counts_p, counts_q):
    alphabet = sorted(counts_p.keys() | counts_q.keys())
    p = [counts_p[s] / sum(counts_p.values()) for s in alphabet]
    q = [counts_q[s] / sum(counts_q.values()) for s in alphabet]
    return entropy([(x+y)/2 for x, y in zip(p, q)]) - (entropy(p)+entropy(q))/2


def contexts(text, symbol, direction):
    # Find symbol positions rather than tabulating adjacent pairs with zip.
    return Counter(text[i+direction] for i, c in enumerate(text)
                   if c == symbol and 0 <= i+direction < len(text))


def score(text, candidate, a, b):
    left = entropy_js(contexts(text, candidate, -1), contexts(text, a, -1))
    right = entropy_js(contexts(text, candidate, 1), contexts(text, b, 1))
    return {'left_js': left, 'bilateral_js': (left+right)/2}


def verify_pair_rows(result):
    checked, maximum = 0, 0
    texts = {}
    for row in result['paired_rows']:
        if not row.get('pairs'):
            continue
        key = row['language'], row['partition']
        if key not in texts:
            texts[key] = experiment.source(*key)
        text = texts[key]
        pool = experiment.matching_pool(text, row['target'], row['decoy'], row['mode'], row['seed'])
        pairs = pool[:len(pool)//2] if row['fraction'] == .5 else pool
        encoded = experiment.plant(text, pairs)
        for candidate in ('X', 'Z'):
            actual = score(encoded, candidate, *row['target'])
            for method, value in actual.items():
                error = abs(value-row['scores'][candidate][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (row, candidate, method, error)
                cutoff = result['thresholds'][method]
                assert experiment.accepted(value, cutoff) == experiment.accepted(row['scores'][candidate][method], cutoff)
                checked += 1
    return checked, maximum


def tables_for(text):
    outgoing = defaultdict(Counter)
    for i in range(len(text)-1):
        outgoing[text[i]][text[i+1]] += 1
    def table(counts):
        symbols = sorted(counts)
        return symbols, list(accumulate(counts[s] for s in symbols))
    starts = table(Counter(w[0] for w in text.split()))
    normal = {c: table(counts) for c, counts in outgoing.items()}
    final = {c: table({s: n for s, n in counts.items() if s != ' '})
             for c, counts in outgoing.items()}
    return starts, normal, final


def direct_text(seed, tables):
    starts, normal, final = tables
    rng = random.Random(seed)
    def draw(table):
        symbols, cumulative = table
        return symbols[bisect.bisect_right(cumulative, rng.randrange(cumulative[-1]))]
    chars = [draw(starts)]
    for i in range(1, 40000):
        table = (final if i == 39999 else normal).get(chars[-1])
        chars.append(draw(table if table and table[0] else starts))
    return ''.join(chars)


def verify_negatives(result):
    checked, maximum = 0, 0
    streams, tables = {}, {}
    for row in result['negative_controls']:
        language, origin, sample = row['language'], row['origin'], row['sample']
        key = language, origin, sample
        if key not in streams:
            if origin == 'natural':
                streams[key] = experiment.source(language, 'evaluation')
            else:
                if language not in tables:
                    tables[language] = tables_for(experiment.source(language, 'training').strip())
                streams[key] = direct_text(sample, tables[language])
        text = streams[key]
        assert hashlib.sha256(text.encode()).hexdigest() == row['sha256']
        for candidate in row['candidates']:
            actual = score(text, candidate['candidate'], *row['target'])
            for method, value in actual.items():
                error = abs(value-candidate['scores'][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (key, row['target'], candidate, error)
                assert experiment.accepted(value, result['thresholds'][method]) == candidate['accepted'][method]
                checked += 1
    return checked, maximum, len(streams)


def main():
    calibration = json.loads((ROOT/'calibration.json').read_bytes())
    evaluation = json.loads((ROOT/'evaluation.json').read_bytes())
    p1, e1 = verify_pair_rows(calibration)
    p2, e2 = verify_pair_rows(evaluation)
    n, e3, samples = verify_negatives(evaluation)
    output = {'paired_js_values_verified': p1+p2, 'negative_js_values_verified': n,
              'distinct_negative_streams_verified': samples,
              'maximum_absolute_js_error': max(e1, e2, e3),
              'all_acceptance_decisions_match': True,
              'all_regenerated_negative_stream_hashes_match': True}
    (ROOT/'verification.json').write_text(json.dumps(output, indent=2))
    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
